package practice;

import java.util.ArrayList;
import java.util.List;
import java.util.random.RandomGenerator;
import java.util.random.RandomGeneratorFactory;

/**
 * Decides which calls fail in one chaos run against the payment gateway. The run is named by
 * its algorithm and seed, which the report prints, so a failure seen in a run can be replayed.
 * Each worker of the run calls failingCalls on its own thread, all of them at the same time.
 */
public class ChaosRun {

    private final String algorithm;
    private final long seed;

    public ChaosRun(String algorithm, long seed) {
        this.algorithm = algorithm;
        this.seed = seed;
    }

    /**
     * The indexes, from 0 to calls - 1, of the calls this worker makes fail: one nextInt(100) draw
     * per call, and the call fails when the draw is below percent.
     */
    public List<Integer> failingCalls(int worker, int calls, int percent) {
        RandomGenerator random = generatorFor(worker);
        List<Integer> failing = new ArrayList<>();
        for (int call = 0; call < calls; call++) {
            if (random.nextInt(100) < percent) failing.add(call);
        }
        return failing;
    }

    /** The generator this worker draws from in this run. */
    RandomGenerator generatorFor(int worker) {
        long workerSeed = seed ^ (0x9E3779B97F4A7C15L * (worker + 1));
        return RandomGeneratorFactory.of(algorithm).create(workerSeed);
    }
}

package practice;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            ChaosRun recorded = new ChaosRun("L64X128MixRandom", 2_026L);
            List<List<Integer>> seen = new ArrayList<>();
            for (int worker = 0; worker < 3; worker++) seen.add(recorded.failingCalls(worker, 20, 25));
            for (int worker = 0; worker < 3; worker++) System.out.println("worker " + worker + " fails calls " + seen.get(worker));
            ChaosRun replay = new ChaosRun("L64X128MixRandom", 2_026L);
            boolean same = true;
            for (int worker = 2; worker >= 0; worker--) same &= replay.failingCalls(worker, 20, 25).equals(seen.get(worker));
            System.out.println("replay, workers started in reverse, fails the same calls: " + same);
            System.out.println("generator of a run named Random: " + new ChaosRun("Random", 9L).generatorFor(0).getClass().getSimpleName());
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

